<span class="line"><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">        image2</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">.</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">jpg</span></span>
